  INSERT INTO course_categories (id, name, description, color) VALUES (cat_hs, 'Health & Safety', 'Workplace health and safety compliance courses', '#EF4444');
  INSERT INTO course_categories (id, name, description, color) VALUES (cat_fs, 'Food Safety', 'Food hygiene and allergen awareness courses', '#F59E0B');
  INSERT INTO course_categories (id, name, description, color) VALUES (cat_co, 'Compliance', 'Legal compliance and regulatory training', '#3B82F6');
  INSERT INTO course_categories (id, name, description, color) VALUES (cat_pr, 'Professional Development', 'Customer service and professional skills', '#8B5CF6');
  INSERT INTO course_categories (id, name, description, color) VALUES (cat_en, 'Environment & Sustainability', 'Energy saving and environmental awareness', '#22C55E');
  INSERT INTO courses (id, title, description, status, template_style, estimated_duration_minutes, category_id, certificate_enabled, passing_score, thumbnail_path)
  INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
    (m, c1, 'Understanding Fire & Fire Risks', 'How fires start and spread', 1),
    (m2, c1, 'Fire Safety Legislation & Risk Assessment', 'UK fire safety law', 2),
    (m3, c1, 'Emergency Procedures & Evacuation', 'What to do in a fire', 3);
  INSERT INTO course_lessons (module_id, title, sort_order, estimated_duration_minutes, content) VALUES
    (m, 'The Fire Triangle', 1, 5, '[{"type":"heading","content":"The Fire Triangle"},{"type":"paragraph","content":"Fire requires three elements: Heat, Fuel, and Oxygen. Remove any one and the fire is extinguished."},{"type":"highlight","content":"CPD Learning Point: Understanding the fire triangle is fundamental to fire prevention."},{"type":"subheading","content":"Heat Sources"},{"type":"bullet_points","items":["Electrical equipment and faulty wiring","Cooking appliances and heating systems","Smoking materials and naked flames","Hot work activities (welding, grinding)"]},{"type":"subheading","content":"Fuel Sources"},{"type":"bullet_points","items":["Paper, cardboard, packaging","Flammable liquids (solvents, cleaning products)","Textiles, soft furnishings","Wood, plastics, rubber","Flammable gases (LPG, natural gas)"]},{"type":"note","content":"Good housekeeping, proper storage, and regular maintenance are key to fire prevention."}]'),
    (m, 'Common Causes of Workplace Fires', 2, 5, '[{"type":"heading","content":"Common Causes of Workplace Fires"},{"type":"paragraph","content":"According to UK Fire Statistics, workplace fires cause millions of pounds in damage each year."},{"type":"bullet_points","items":["Electrical faults (25%)","Arson (20%)","Cooking equipment (15%)","Smoking materials (10%)","Heating equipment (8%)"]},{"type":"highlight","content":"Electrical faults are the single biggest cause of accidental workplace fires in the UK."},{"type":"infobox","content":"Under the RRFSO 2005, the Responsible Person must reduce fire risk and ensure safe evacuation."}]'),
    (m, 'Fire Classification', 3, 5, '[{"type":"heading","content":"Classes of Fire"},{"type":"paragraph","content":"Using the correct extinguisher for each class is critical."},{"type":"subheading","content":"Class A — Solids"},{"type":"paragraph","content":"Wood, paper, textiles. Use water, foam, or dry powder."},{"type":"subheading","content":"Class B — Flammable Liquids"},{"type":"paragraph","content":"Petrol, oil, solvents. Use foam, CO2, or dry powder."},{"type":"subheading","content":"Class C — Flammable Gases"},{"type":"paragraph","content":"Propane, butane. Use dry powder."},{"type":"subheading","content":"Class F — Cooking Oils"},{"type":"paragraph","content":"Use wet chemical ONLY. NEVER use water."},{"type":"note","content":"Always check the extinguisher label before use."}]'),
    (m2, 'UK Fire Safety Legislation', 1, 5, '[{"type":"heading","content":"UK Fire Safety Legislation"},{"type":"paragraph","content":"The Regulatory Reform (Fire Safety) Order 2005 governs fire safety in England and Wales."},{"type":"bullet_points","items":["A Responsible Person must be appointed","Fire risk assessment is mandatory","Fire safety measures must be maintained","Employees must receive training","Detection and warning systems required"]},{"type":"highlight","content":"The Responsible Person is usually the employer or building owner."},{"type":"infobox","content":"Non-compliance can result in unlimited fines or imprisonment."}]'),
    (m2, 'Fire Risk Assessment', 2, 5, '[{"type":"heading","content":"Fire Risk Assessment — 5 Steps"},{"type":"bullet_points","items":["Step 1: Identify fire hazards","Step 2: Identify people at risk","Step 3: Evaluate and reduce risk","Step 4: Record findings and prepare emergency plan","Step 5: Review and update regularly"]},{"type":"highlight","content":"PEEPs must be prepared for anyone needing evacuation assistance."},{"type":"note","content":"Review at least annually or after significant workplace changes."}]'),
    (m2, 'Fire Prevention Strategies', 3, 5, '[{"type":"heading","content":"Fire Prevention Strategies"},{"type":"subheading","content":"Housekeeping"},{"type":"bullet_points","items":["Keep workplaces clean","Remove waste regularly","Store flammables properly","Keep escape routes clear","Never block fire doors"]},{"type":"subheading","content":"Electrical Safety"},{"type":"bullet_points","items":["Regular PAT testing","No overloaded sockets","Report damaged cables","Switch off unused equipment"]},{"type":"infobox","content":"Fire doors must never be propped open unless fitted with automatic closers linked to the alarm."}]'),
    (m3, 'Evacuation Procedures', 1, 5, '[{"type":"heading","content":"Fire Alarm & Evacuation"},{"type":"subheading","content":"On Discovering a Fire"},{"type":"bullet_points","items":["Sound the alarm","Call 999","Only fight small fires if trained","Close doors behind you","Evacuate via nearest safe route"]},{"type":"subheading","content":"On Hearing the Alarm"},{"type":"bullet_points","items":["Stop immediately","Leave by nearest exit","Do not use lifts","Do not collect belongings","Go to assembly point"]},{"type":"highlight","content":"NEVER re-enter until declared safe."}]'),
    (m3, 'Fire Safety Equipment', 2, 5, '[{"type":"heading","content":"Fire Safety Equipment"},{"type":"bullet_points","items":["RED (Water) — Class A","CREAM (Foam) — Class A & B","BLUE (Dry Powder) — A, B, C & electrical","BLACK (CO2) — B & electrical","YELLOW (Wet Chemical) — Class F"]},{"type":"infobox","content":"All equipment must be inspected annually."}]'),
    (m3, 'Fire Warden Responsibilities', 3, 5, '[{"type":"heading","content":"Fire Warden Responsibilities"},{"type":"bullet_points","items":["Conduct regular safety checks","Ensure exits are clear","Coordinate evacuation","Conduct roll calls","Liaise with Fire Service"]},{"type":"highlight","content":"This CPD course meets RRFSO 2005 requirements for fire safety awareness training."}]');
  INSERT INTO courses (id, title, description, status, template_style, estimated_duration_minutes, category_id, certificate_enabled, passing_score, thumbnail_path)
  INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
    (m, c2, 'Introduction to Manual Handling', 'Understanding risks', 1),
    (m2, c2, 'Safe Lifting Techniques', 'Correct posture and methods', 2),
    (m3, c2, 'Risk Assessment & Prevention', 'TILE assessment', 3);
  INSERT INTO course_lessons (module_id, title, sort_order, estimated_duration_minutes, content) VALUES
    (m, 'What is Manual Handling?', 1, 6, '[{"type":"heading","content":"What is Manual Handling?"},{"type":"paragraph","content":"Manual handling means transporting or supporting a load by hand or bodily force — lifting, pushing, pulling, carrying, or moving."},{"type":"highlight","content":"Over one third of all workplace injuries are caused by manual handling."},{"type":"subheading","content":"The Regulations"},{"type":"paragraph","content":"The Manual Handling Operations Regulations 1992 require employers to avoid hazardous operations, assess unavoidable ones, and reduce risk."},{"type":"note","content":"There are no specific weight limits in UK law. Risk depends on load, task, environment, and individual capability."}]'),
    (m, 'Common Injuries', 2, 6, '[{"type":"heading","content":"Common Manual Handling Injuries"},{"type":"bullet_points","items":["Back injuries — herniated discs, muscle strains, sciatica","Upper limb disorders — shoulder impingement, carpal tunnel","Hernias from heavy lifting","Cuts and crush injuries from dropped loads"]},{"type":"highlight","content":"Back injuries account for over 40% of all manual handling injuries."},{"type":"infobox","content":"In 2024/25, MSDs accounted for 6.6 million working days lost in the UK."}]'),
    (m2, 'Safe Lifting — Step by Step', 1, 6, '[{"type":"heading","content":"Safe Lifting Technique"},{"type":"subheading","content":"Before You Lift"},{"type":"bullet_points","items":["Where is the load going? Is the route clear?","Can you use a mechanical aid?","Do you need help?","Wearing appropriate footwear?"]},{"type":"subheading","content":"The 8 Steps"},{"type":"bullet_points","items":["1. Feet shoulder-width apart, one slightly forward","2. Bend knees, not back","3. Firm grip with whole hand","4. Keep load close to body","5. Lift with leg muscles","6. Keep back straight, avoid twisting","7. Look ahead, not down","8. Put down by reversing — bend knees"]},{"type":"highlight","content":"Golden rule: Lift with legs, not back. Keep load close."}]'),
    (m2, 'Team Lifting & Mechanical Aids', 2, 6, '[{"type":"heading","content":"Team Lifting & Mechanical Aids"},{"type":"subheading","content":"Team Lifting"},{"type":"bullet_points","items":["One person coordinates","Similar height team members","Lift on coordinators signal","Communicate throughout"]},{"type":"subheading","content":"Mechanical Aids"},{"type":"bullet_points","items":["Trolleys and sack barrows","Pallet trucks","Conveyor belts","Hoists and cranes"]},{"type":"note","content":"Always use mechanical aids when available."}]'),
    (m3, 'The TILE Assessment', 1, 6, '[{"type":"heading","content":"TILE Risk Assessment"},{"type":"subheading","content":"T — Task"},{"type":"bullet_points","items":["Twisting, stooping, reaching?","Prolonged holding?","Repetitive lifting?"]},{"type":"subheading","content":"I — Individual"},{"type":"bullet_points","items":["Physical capability?","Health conditions?","Training received?"]},{"type":"subheading","content":"L — Load"},{"type":"bullet_points","items":["How heavy?","Bulky or unstable?","Hot, cold, or sharp?"]},{"type":"subheading","content":"E — Environment"},{"type":"bullet_points","items":["Floors wet or uneven?","Adequate space and lighting?","Stairs or slopes?"]},{"type":"highlight","content":"Use TILE before every manual handling task."}]'),
    (m3, 'Reporting & Best Practice', 2, 5, '[{"type":"heading","content":"Reporting & Best Practice"},{"type":"bullet_points","items":["Report all injuries, even minor","Report near misses","Report unsafe tasks","Suggest improvements"]},{"type":"subheading","content":"Best Practice"},{"type":"bullet_points","items":["Always plan your lift","Use mechanical aids","Ask for help when needed","Take regular breaks","Stay fit and healthy","Annual refresher training"]},{"type":"highlight","content":"This CPD course meets the Manual Handling Operations Regulations 1992 training requirements."}]');
  INSERT INTO courses (id, title, description, status, template_style, estimated_duration_minutes, category_id, certificate_enabled, passing_score, thumbnail_path)
  INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
    (m, c3, 'Understanding COSHH', 'What COSHH is and why it matters', 1),
    (m2, c3, 'Hazardous Substances & Symbols', 'Identifying hazards and reading SDS', 2),
    (m3, c3, 'COSHH Assessment & Controls', 'Assessments and control measures', 3);
  INSERT INTO course_lessons (module_id, title, sort_order, estimated_duration_minutes, content) VALUES
    (m, 'Introduction to COSHH', 1, 6, '[{"type":"heading","content":"Introduction to COSHH"},{"type":"paragraph","content":"COSHH stands for Control of Substances Hazardous to Health. The Regulations 2002 require employers to control hazardous substances."},{"type":"bullet_points","items":["Chemicals used in cleaning and maintenance","Fumes, dust, and vapours","Biological agents","Substances with workplace exposure limits"]},{"type":"highlight","content":"Thousands of workers are made ill every year by hazardous substances."},{"type":"note","content":"COSHH does not cover lead, asbestos, or radioactive substances."}]'),
    (m, 'Routes of Exposure', 2, 6, '[{"type":"heading","content":"Routes of Exposure"},{"type":"subheading","content":"Inhalation"},{"type":"paragraph","content":"Most common route. Dusts, fumes, vapours can be inhaled."},{"type":"subheading","content":"Skin Absorption"},{"type":"paragraph","content":"Many chemicals pass through skin into the bloodstream."},{"type":"subheading","content":"Ingestion"},{"type":"paragraph","content":"Eating without washing hands after handling substances."},{"type":"subheading","content":"Injection"},{"type":"paragraph","content":"Through cuts, wounds, or sharp contaminated objects."},{"type":"infobox","content":"Always wash hands after handling any hazardous substance."}]'),
    (m2, 'GHS Hazard Symbols', 1, 6, '[{"type":"heading","content":"GHS Hazard Symbols"},{"type":"paragraph","content":"The Globally Harmonised System uses red diamond pictograms."},{"type":"bullet_points","items":["Skull & Crossbones — Toxic/Fatal","Exclamation Mark — Irritant/Harmful","Health Hazard — Carcinogenic/Mutagenic","Flame — Flammable","Flame over Circle — Oxidiser","Corrosion — Burns/Eye damage","Gas Cylinder — Pressurised gas","Exploding Bomb — Explosive","Environment — Aquatic hazard"]},{"type":"highlight","content":"If you see a red diamond, read the Safety Data Sheet before use."}]'),
    (m2, 'Reading Product Labels', 2, 5, '[{"type":"heading","content":"Reading Product Labels"},{"type":"bullet_points","items":["Product name and composition","GHS hazard pictograms","Signal word (DANGER or WARNING)","Hazard statements (H-phrases)","Precautionary statements (P-phrases)","Supplier information"]},{"type":"highlight","content":"DANGER indicates more severe hazards than WARNING."},{"type":"note","content":"Never decant substances into unlabelled containers."}]'),
    (m3, 'COSHH Risk Assessment', 1, 6, '[{"type":"heading","content":"COSHH Risk Assessment"},{"type":"bullet_points","items":["1. Identify hazardous substances","2. Identify who is exposed and how","3. Evaluate risk and decide precautions","4. Record and implement controls","5. Review regularly"]},{"type":"subheading","content":"Hierarchy of Control"},{"type":"bullet_points","items":["Elimination","Substitution","Engineering controls","Administrative controls","PPE (last resort)"]},{"type":"infobox","content":"PPE should always be the last resort, not the first line of defence."}]'),
    (m3, 'PPE & Emergency Procedures', 2, 6, '[{"type":"heading","content":"PPE & Emergency Procedures"},{"type":"bullet_points","items":["Chemical-resistant gloves","Safety goggles or face shields","Respiratory protective equipment","Chemical-resistant aprons","Safety boots"]},{"type":"subheading","content":"Emergencies"},{"type":"bullet_points","items":["Know emergency shower and eyewash locations","Know spill kit locations","Report all spills and exposures immediately","Follow SDS first aid guidance"]},{"type":"highlight","content":"This CPD course meets COSHH Regulations 2002 training requirements."}]');
  INSERT INTO courses (id, title, description, status, template_style, estimated_duration_minutes, category_id, certificate_enabled, passing_score, thumbnail_path)
  INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
    (m, c4, 'Age-Restricted Products', 'UK law on age restrictions', 1),
    (m2, c4, 'Challenge 25 & Acceptable ID', 'Verifying age', 2),
    (m3, c4, 'Refusing Sales & Records', 'How to refuse and record', 3);
  INSERT INTO course_lessons (module_id, title, sort_order, estimated_duration_minutes, content) VALUES
    (m, 'Age-Restricted Products in the UK', 1, 5, '[{"type":"heading","content":"Age-Restricted Products"},{"type":"subheading","content":"Age 18 Products"},{"type":"bullet_points","items":["Alcohol","Tobacco, e-cigarettes, vapes","Knives and bladed articles","Fireworks (F2/F3)","Solvents","Spray paint","Lottery tickets"]},{"type":"highlight","content":"YOU are personally liable. Fines up to £5,000 and a criminal record."}]'),
    (m2, 'The Challenge 25 Policy', 1, 5, '[{"type":"heading","content":"Challenge 25"},{"type":"paragraph","content":"If a customer looks under 25, you MUST ask for valid photo ID."},{"type":"subheading","content":"Acceptable ID"},{"type":"bullet_points","items":["Passport (UK or foreign)","UK photocard driving licence","PASS accredited card (with hologram)","Military ID"]},{"type":"highlight","content":"Student cards and work badges are NOT acceptable."},{"type":"subheading","content":"FAIL Method"},{"type":"bullet_points","items":["F — Face matches photo?","A — Age from date of birth?","I — Acceptable ID type?","L — Legitimate (holograms, validity)?"]},{"type":"note","content":"If in doubt, refuse the sale."}]'),
    (m2, 'Proxy Sales & Test Purchases', 2, 5, '[{"type":"heading","content":"Proxy Sales"},{"type":"paragraph","content":"An adult buying for an underage person is illegal. Refuse if suspected."},{"type":"bullet_points","items":["Young people waiting outside","Customer consulting with others","Unusual purchase patterns","Money passed by younger individuals"]},{"type":"subheading","content":"Test Purchases"},{"type":"paragraph","content":"Trading Standards conduct regular test purchases. Selling to a test purchaser means prosecution."},{"type":"infobox","content":"Record all refusals — this demonstrates due diligence."}]'),
    (m3, 'Refusing Sales & Record Keeping', 1, 5, '[{"type":"heading","content":"How to Refuse Professionally"},{"type":"bullet_points","items":["Be polite but firm","Explain it is the law","Offer to serve with valid ID","Do not be intimidated","Call manager if threatened"]},{"type":"subheading","content":"Refusals Log"},{"type":"bullet_points","items":["Date and time","Product refused","Customer description","Reason for refusal","Staff member name"]},{"type":"highlight","content":"A well-maintained refusals log demonstrates compliance."},{"type":"note","content":"This CPD course meets UK retail standards for underage sales training."}]');
  INSERT INTO courses (id, title, description, status, template_style, estimated_duration_minutes, category_id, certificate_enabled, passing_score, thumbnail_path)
  INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
    (m, c5, 'Understanding Food Allergies', 'What allergies are', 1),
    (m2, c5, 'The 14 Declarable Allergens', 'Each allergen explained', 2),
    (m3, c5, 'Allergen Management & Law', 'Legal requirements', 3);
  INSERT INTO course_lessons (module_id, title, sort_order, estimated_duration_minutes, content) VALUES
    (m, 'What is a Food Allergy?', 1, 5, '[{"type":"heading","content":"Understanding Food Allergies"},{"type":"paragraph","content":"A food allergy is an immune system reaction. Even tiny amounts can trigger life-threatening symptoms."},{"type":"bullet_points","items":["Food allergy — immune response, can be fatal","Food intolerance — digestive, uncomfortable but not fatal","Coeliac disease — autoimmune, triggered by gluten"]},{"type":"highlight","content":"Around 2 million people in the UK have a diagnosed food allergy. ~10 deaths per year."},{"type":"subheading","content":"Anaphylaxis"},{"type":"paragraph","content":"Severe reaction: throat swelling, breathing difficulty, blood pressure drop. Requires EpiPen and 999 call."},{"type":"note","content":"Never assume a customer is exaggerating. Take every enquiry seriously."}]'),
    (m2, 'The 14 Allergens (Part 1)', 1, 7, '[{"type":"heading","content":"The 14 Declarable Allergens — Part 1"},{"type":"subheading","content":"1. Celery"},{"type":"paragraph","content":"Found in stocks, soups, salads."},{"type":"subheading","content":"2. Cereals with Gluten"},{"type":"paragraph","content":"Wheat, rye, barley, oats. In bread, pasta, sauces."},{"type":"subheading","content":"3. Crustaceans"},{"type":"paragraph","content":"Prawns, crabs, lobster. In Asian cuisine, fish sauce."},{"type":"subheading","content":"4. Eggs"},{"type":"paragraph","content":"In cakes, sauces, pasta, mayonnaise."},{"type":"subheading","content":"5. Fish"},{"type":"paragraph","content":"In Worcestershire sauce, Asian cuisine."},{"type":"subheading","content":"6. Lupin"},{"type":"paragraph","content":"In flour, bread, pastries."},{"type":"subheading","content":"7. Milk"},{"type":"paragraph","content":"In butter, cheese, crisps, sausages."}]'),
    (m2, 'The 14 Allergens (Part 2)', 2, 7, '[{"type":"heading","content":"The 14 Allergens — Part 2"},{"type":"subheading","content":"8. Molluscs"},{"type":"paragraph","content":"Mussels, squid, oysters."},{"type":"subheading","content":"9. Mustard"},{"type":"paragraph","content":"In dressings, marinades, curries."},{"type":"subheading","content":"10. Tree Nuts"},{"type":"paragraph","content":"Almonds, walnuts, cashews, etc."},{"type":"subheading","content":"11. Peanuts"},{"type":"paragraph","content":"In sauces, Asian/African dishes."},{"type":"subheading","content":"12. Sesame"},{"type":"paragraph","content":"In bread, hummus, tahini."},{"type":"subheading","content":"13. Soya"},{"type":"paragraph","content":"In tofu, processed foods, ice cream."},{"type":"subheading","content":"14. Sulphites"},{"type":"paragraph","content":"In dried fruits, wine, sausages."},{"type":"highlight","content":"You must identify all 14 allergens in your products."}]'),
    (m3, 'Natashas Law & Labelling', 1, 6, '[{"type":"heading","content":"Natashas Law"},{"type":"paragraph","content":"Effective 1 October 2021, following the death of Natasha Ednan-Laperouse."},{"type":"paragraph","content":"All Prepacked for Direct Sale (PPDS) food must have full ingredient labels with allergens in bold."},{"type":"bullet_points","items":["Pre-packed — full labelling always required","PPDS — NOW requires full labelling","Non-prepacked (loose) — info available on request"]},{"type":"highlight","content":"PPDS includes sandwiches and baked goods wrapped on premises."}]'),
    (m3, 'Managing Allergens Safely', 2, 5, '[{"type":"heading","content":"Allergen Management"},{"type":"subheading","content":"Preventing Cross-Contamination"},{"type":"bullet_points","items":["Store allergen foods separately","Use separate utensils","Clean surfaces between tasks","Wash hands between foods","Label all items clearly","Change gloves between foods"]},{"type":"subheading","content":"Communication"},{"type":"bullet_points","items":["Always ask about allergies","Provide accurate info — verify if unsure","Never guess","Update info when recipes change"]},{"type":"highlight","content":"This CPD course meets UK food allergen awareness standards."}]');
  INSERT INTO courses (id, title, description, status, template_style, estimated_duration_minutes, category_id, certificate_enabled, passing_score, thumbnail_path)
  INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
    (m, c6, 'Cyber Threats & Risks', 'Common threats', 1),
    (m2, c6, 'Protecting Yourself', 'Passwords and data protection', 2),
    (m3, c6, 'Incident Response', 'What to do if breached', 3);
  INSERT INTO course_lessons (module_id, title, sort_order, estimated_duration_minutes, content) VALUES
    (m, 'The Cyber Threat Landscape', 1, 6, '[{"type":"heading","content":"Cyber Threats"},{"type":"paragraph","content":"39% of UK businesses identified a cyber attack in the last year. Average cost: £4,960."},{"type":"bullet_points","items":["Phishing — fraudulent emails","Ransomware — encrypts files for ransom","Social engineering — manipulating people","Malware — viruses, trojans, spyware","Business Email Compromise"]},{"type":"highlight","content":"Human error causes 95% of cyber breaches."}]'),
    (m, 'Phishing & Social Engineering', 2, 6, '[{"type":"heading","content":"Phishing"},{"type":"bullet_points","items":["Email phishing — mass emails","Spear phishing — targeted","Whaling — targeting executives","Smishing — via SMS","Vishing — via phone"]},{"type":"subheading","content":"Red Flags"},{"type":"bullet_points","items":["Urgent/threatening language","Unexpected attachments","Mismatched sender address","Generic greetings","Poor spelling/grammar","Requests for passwords or payments"]},{"type":"highlight","content":"STOP — THINK — CHECK. Report suspicious emails."}]'),
    (m2, 'Password Security', 1, 6, '[{"type":"heading","content":"Password Security"},{"type":"bullet_points","items":["Use 12+ characters","Mix upper/lower, numbers, symbols","Use three random words (NCSC recommendation)","Different password per account"]},{"type":"subheading","content":"Dos and Donts"},{"type":"bullet_points","items":["DO use a password manager","DO enable MFA everywhere","DONT share passwords","DONT write them on sticky notes","DONT reuse across accounts"]},{"type":"highlight","content":"MFA reduces compromise risk by 99.9%."}]'),
    (m2, 'Data Protection & GDPR', 2, 6, '[{"type":"heading","content":"Data Protection"},{"type":"paragraph","content":"Under UK GDPR, breaches involving personal data must be reported to the ICO within 72 hours."},{"type":"bullet_points","items":["Lock computer when away (Win+L)","Clear desk policy","Encrypt laptops and USBs","Only access data you need","Shred sensitive documents"]},{"type":"subheading","content":"Remote Working"},{"type":"bullet_points","items":["Use company VPN","No public WiFi for work","Secure home WiFi","Separate work and personal devices"]},{"type":"infobox","content":"GDPR fines can reach £17.5 million or 4% of global turnover."}]'),
    (m3, 'Incident Response', 1, 5, '[{"type":"heading","content":"If You Suspect a Breach"},{"type":"bullet_points","items":["Report to IT immediately","Dont try to fix it yourself","Dont delete evidence","Disconnect if instructed","Note what happened and when"]},{"type":"subheading","content":"Signs of a Breach"},{"type":"bullet_points","items":["Unexpected pop-ups","Slow computer","Missing/encrypted files","Unfamiliar programs","Emails you didnt send"]},{"type":"highlight","content":"This CPD course meets UK cyber security awareness standards. NCSC recommends annual refresher training."}]');
  INSERT INTO courses (id, title, description, status, template_style, estimated_duration_minutes, category_id, certificate_enabled, passing_score, thumbnail_path)
  INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
    (m, c7, 'Why Energy Matters', 'Business and environmental case', 1),
    (m2, c7, 'Practical Energy Saving', 'Actions to reduce consumption', 2);
  INSERT INTO course_lessons (module_id, title, sort_order, estimated_duration_minutes, content) VALUES
    (m, 'The Business Case', 1, 5, '[{"type":"heading","content":"Why Energy Efficiency Matters"},{"type":"bullet_points","items":["Reduced operating costs","Lower carbon emissions","Regulatory compliance","Better reputation","Improved working conditions"]},{"type":"highlight","content":"UK businesses waste up to 20% of their energy. Simple changes save 10-15%."},{"type":"note","content":"The UK committed to Net Zero by 2050."}]'),
    (m, 'Understanding Energy Use', 2, 5, '[{"type":"heading","content":"Where Energy Goes"},{"type":"bullet_points","items":["Heating & cooling — 40-50%","Lighting — 20-25%","Refrigeration — 15-20%","IT equipment — 10-15%","Hot water — 5-10%"]},{"type":"infobox","content":"A 100W bulb on 10 hours = 1 kWh ≈ 30p. Multiply by hundreds of lights across a year."}]'),
    (m2, 'Everyday Energy Saving', 1, 7, '[{"type":"heading","content":"Everyday Actions"},{"type":"subheading","content":"Lighting"},{"type":"bullet_points","items":["Switch off in empty areas","Use natural daylight","Report broken sensors","Replace with LED (75% less energy)"]},{"type":"subheading","content":"Heating"},{"type":"bullet_points","items":["Set to 19°C (1°C less = 8% saving)","Dont heat unused areas","Report draughts","No portable heaters","Keep doors closed"]},{"type":"subheading","content":"Equipment"},{"type":"bullet_points","items":["Switch off computers at end of day","Use power-saving modes","Unplug chargers","Turn off printers overnight"]},{"type":"highlight","content":"Small actions by many people create significant savings."}]'),
    (m2, 'Energy Champions', 2, 5, '[{"type":"heading","content":"Be an Energy Champion"},{"type":"bullet_points","items":["Lead by example","Encourage colleagues","Suggest improvements","Monitor energy use","Celebrate successes"]},{"type":"subheading","content":"Monitoring"},{"type":"bullet_points","items":["Read meters regularly","Look for consumption spikes","Check timers and sensors","Review bills for accuracy"]},{"type":"highlight","content":"This CPD course is accredited for environmental awareness. The greenest energy is the energy we dont use."}]');
  INSERT INTO courses (id, title, description, status, template_style, estimated_duration_minutes, category_id, certificate_enabled, passing_score, thumbnail_path)
  INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
    (m, c8, 'Types of Extinguishers', 'The 5 main types', 1),
    (m2, c8, 'Selecting the Right One', 'Matching to fire classes', 2),
    (m3, c8, 'Using Extinguishers — PASS', 'The PASS technique', 3);
  INSERT INTO course_lessons (module_id, title, sort_order, estimated_duration_minutes, content) VALUES
    (m, 'The 5 Types', 1, 5, '[{"type":"heading","content":"Fire Extinguisher Types"},{"type":"subheading","content":"1. Water (Red)"},{"type":"paragraph","content":"Class A only. Cools the fire. Never on electrical or oil fires."},{"type":"subheading","content":"2. Foam (Cream)"},{"type":"paragraph","content":"Class A & B. Smothers and cools."},{"type":"subheading","content":"3. Dry Powder (Blue)"},{"type":"paragraph","content":"Class A, B, C & electrical. Creates visibility-reducing cloud."},{"type":"subheading","content":"4. CO2 (Black)"},{"type":"paragraph","content":"Class B & electrical. Horn gets extremely cold."},{"type":"subheading","content":"5. Wet Chemical (Yellow)"},{"type":"paragraph","content":"Class F only (cooking oils). The ONLY choice for deep fat fryers."},{"type":"note","content":"Using the wrong type can be deadly."}]'),
    (m2, 'Fire Class Reference', 1, 5, '[{"type":"heading","content":"Quick Reference"},{"type":"bullet_points","items":["Class A (Solids) — Water, Foam, Powder","Class B (Liquids) — Foam, CO2, Powder","Class C (Gases) — Powder only","Electrical — CO2 or Powder","Class F (Oils) — Wet Chemical ONLY"]},{"type":"highlight","content":"When in doubt, dont fight it. Sound alarm and evacuate."}]'),
    (m3, 'The PASS Technique', 1, 5, '[{"type":"heading","content":"P.A.S.S."},{"type":"subheading","content":"P — Pull"},{"type":"paragraph","content":"Pull the pin or safety clip."},{"type":"subheading","content":"A — Aim"},{"type":"paragraph","content":"Aim at the BASE of the fire."},{"type":"subheading","content":"S — Squeeze"},{"type":"paragraph","content":"Squeeze the lever to discharge."},{"type":"subheading","content":"S — Sweep"},{"type":"paragraph","content":"Sweep side to side across the base."},{"type":"highlight","content":"Most extinguishers last 10-60 seconds."},{"type":"infobox","content":"Only fight a fire if: it is small, you have the right extinguisher, you have a clear escape route, and the alarm is raised."}]'),
    (m3, 'Safety & Maintenance', 2, 5, '[{"type":"heading","content":"Safety & Maintenance"},{"type":"subheading","content":"When NOT to Fight"},{"type":"bullet_points","items":["Fire too large or spreading","Wrong extinguisher type","Smoke filling room","Escape route threatened","You are unsure"]},{"type":"subheading","content":"Maintenance"},{"type":"bullet_points","items":["Monthly visual check","Annual service (BS 5306-3)","Extended service every 5 years","Replace after any use","Gauge in green zone"]},{"type":"highlight","content":"This CPD course provides theoretical training. Practical hands-on training also recommended."}]');
  INSERT INTO courses (id, title, description, status, template_style, estimated_duration_minutes, category_id, certificate_enabled, passing_score, thumbnail_path)
  INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
    (m, c9, 'Foundations of Service', 'What great service looks like', 1),
    (m2, c9, 'Communication & Interaction', 'Effective techniques', 2),
    (m3, c9, 'Complaints & Difficult Situations', 'Turning problems into opportunities', 3);
  INSERT INTO course_lessons (module_id, title, sort_order, estimated_duration_minutes, content) VALUES
    (m, 'What is Service Excellence?', 1, 5, '[{"type":"heading","content":"Customer Service Excellence"},{"type":"paragraph","content":"Excellence means consistently delivering experiences that surprise and delight."},{"type":"bullet_points","items":["86% of customers pay more for better experience","5x more costly to gain new vs keep existing","68% leave due to perceived indifference","Loyal customers spend 67% more"]},{"type":"highlight","content":"You are the face of the business."}]'),
    (m, 'First Impressions & Body Language', 2, 5, '[{"type":"heading","content":"First Impressions"},{"type":"paragraph","content":"Formed within 7 seconds. 55% body language, 38% tone, 7% words."},{"type":"bullet_points","items":["Smile genuinely","Make eye contact","Professional posture","Greet within 10 seconds","Open body language"]},{"type":"infobox","content":"The 10-5 Rule: At 10 feet acknowledge, at 5 feet greet verbally."}]'),
    (m2, 'Active Listening', 1, 5, '[{"type":"heading","content":"Active Listening"},{"type":"bullet_points","items":["Give full attention","Maintain eye contact","Nod and acknowledge","Dont interrupt","Paraphrase to confirm","Ask clarifying questions"]},{"type":"highlight","content":"When customers feel heard, they are more satisfied even without the perfect outcome."}]'),
    (m2, 'Going Above and Beyond', 2, 5, '[{"type":"heading","content":"Exceeding Expectations"},{"type":"bullet_points","items":["Remember regular customers","Offer help before asked","Provide useful information","Follow up on purchases","Offer alternatives","Small gestures of kindness"]},{"type":"quote","content":"People will never forget how you made them feel. — Maya Angelou"}]'),
    (m3, 'Complaints — The HEAT Method', 1, 5, '[{"type":"heading","content":"The HEAT Method"},{"type":"paragraph","content":"95% of customers whose complaint is resolved become loyal."},{"type":"subheading","content":"H — Hear Them Out"},{"type":"paragraph","content":"Listen fully without interrupting."},{"type":"subheading","content":"E — Empathise"},{"type":"paragraph","content":"Show understanding of their frustration."},{"type":"subheading","content":"A — Apologise"},{"type":"paragraph","content":"Genuine apology for their experience."},{"type":"subheading","content":"T — Take Action"},{"type":"paragraph","content":"Explain what you will do. Follow through."},{"type":"highlight","content":"Never argue with a customer."}]'),
    (m3, 'Difficult Customers', 2, 5, '[{"type":"heading","content":"De-escalation"},{"type":"bullet_points","items":["Stay calm and professional","Lower voice and slow speech","Use customers name","Acknowledge feelings first","Move to quieter area","Offer solutions not excuses"]},{"type":"paragraph","content":"If a customer becomes abusive, you have the right to step away and get your manager."},{"type":"highlight","content":"This CPD course is accredited for UK retail and hospitality."}]');
  INSERT INTO courses (id, title, description, status, template_style, estimated_duration_minutes, category_id, certificate_enabled, passing_score, thumbnail_path)
  INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
    (m, c10, 'First Aid Fundamentals', 'Responsibilities and basics', 1),
    (m2, c10, 'Primary Survey & CPR', 'DR ABC and life support awareness', 2),
    (m3, c10, 'Common Workplace Injuries', 'Burns, cuts, fractures, shock', 3);
  INSERT INTO course_lessons (module_id, title, sort_order, estimated_duration_minutes, content) VALUES
    (m, 'Introduction to First Aid', 1, 5, '[{"type":"heading","content":"First Aid at Work"},{"type":"paragraph","content":"The Health and Safety (First Aid) Regulations 1981 set out employer responsibilities."},{"type":"bullet_points","items":["Provide first aid equipment","Appoint sufficient first aiders","Display first aid information","Record all incidents"]},{"type":"subheading","content":"Aims of First Aid"},{"type":"bullet_points","items":["Preserve life","Prevent worsening","Promote recovery"]},{"type":"highlight","content":"This is AWARENESS training only. Practical qualifications require hands-on training."}]'),
    (m, 'Scene Safety & Calling 999', 2, 5, '[{"type":"heading","content":"Scene Safety"},{"type":"bullet_points","items":["Check for dangers","Count casualties","Find bystanders to help","Ensure safe to approach"]},{"type":"subheading","content":"Calling 999"},{"type":"bullet_points","items":["Your location (postcode)","What happened","Number and condition of casualties","Hazards present","Your name and callback number"]},{"type":"highlight","content":"Always call 999 first if life-threatening."},{"type":"infobox","content":"Send someone for the nearest AED immediately."}]'),
    (m2, 'DR ABC Primary Survey', 1, 7, '[{"type":"heading","content":"DR ABC"},{"type":"subheading","content":"D — Danger"},{"type":"paragraph","content":"Check for danger to yourself, bystanders, casualty."},{"type":"subheading","content":"R — Response"},{"type":"paragraph","content":"Shake shoulders gently. Ask loudly: Can you hear me?"},{"type":"subheading","content":"A — Airway"},{"type":"paragraph","content":"Tilt head back, lift chin. Check for obstructions."},{"type":"subheading","content":"B — Breathing"},{"type":"paragraph","content":"Look, listen, feel for 10 seconds."},{"type":"subheading","content":"C — Circulation"},{"type":"paragraph","content":"Check for severe bleeding. Apply direct pressure."},{"type":"highlight","content":"Not breathing? Call 999 and begin CPR if trained."}]'),
    (m2, 'CPR & AED Awareness', 2, 7, '[{"type":"heading","content":"CPR & AED Awareness"},{"type":"subheading","content":"Hands-Only CPR"},{"type":"bullet_points","items":["Heel of hand on centre of chest","Other hand on top, interlock fingers","Push hard and fast — 100-120/min","Depth 5-6 cm","Allow full recoil","Continue until paramedics arrive"]},{"type":"subheading","content":"AED"},{"type":"bullet_points","items":["Switch on, follow voice prompts","Attach pads to bare chest","Stand clear during analysis","Shock if advised","Continue CPR between analyses"]},{"type":"highlight","content":"Every minute without CPR/defib, survival drops 10%."},{"type":"note","content":"This is awareness only. Complete practical training for certification."}]'),
    (m3, 'Burns, Cuts & Bleeding', 1, 7, '[{"type":"heading","content":"Burns & Bleeding"},{"type":"subheading","content":"Burns"},{"type":"bullet_points","items":["Cool under running water 20 minutes","Remove clothing if not stuck","Cover with cling film","No creams, butter, or ice","Dont burst blisters"]},{"type":"subheading","content":"Severe Bleeding"},{"type":"bullet_points","items":["Direct pressure with clean pad","Elevate the limb","Bandage firmly","If soaks through, add another pad","Call 999 for severe bleeding"]},{"type":"infobox","content":"Always wear gloves when dealing with blood."}]'),
    (m3, 'Shock, Fractures & Choking', 2, 7, '[{"type":"heading","content":"Shock & Fractures"},{"type":"subheading","content":"Shock"},{"type":"bullet_points","items":["Signs: pale, cold, clammy, rapid breathing","Lay down, raise legs","Keep warm","No food or drink","Call 999"]},{"type":"subheading","content":"Fractures"},{"type":"bullet_points","items":["Immobilise the area","Support with padding","Apply ice pack in cloth","Dont move if spinal injury suspected"]},{"type":"subheading","content":"Choking"},{"type":"bullet_points","items":["Encourage coughing","5 back blows","5 abdominal thrusts","Alternate until clear","Call 999 if not clearing"]},{"type":"highlight","content":"This CPD course meets Health and Safety (First Aid) Regulations 1981 awareness requirements."}]');
  INSERT INTO courses (id, title, description, status, template_style, estimated_duration_minutes, category_id, certificate_enabled, passing_score, thumbnail_path)
  INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
    (m, c11, 'Roll Cage Hazards', 'Understanding the dangers', 1),
    (m2, c11, 'Safe Handling Techniques', 'Correct methods', 2),
    (m3, c11, 'Inspection & Loading', 'Pre-use checks and loading', 3);
  INSERT INTO course_lessons (module_id, title, sort_order, estimated_duration_minutes, content) VALUES
    (m, 'Introduction to Roll Cage Safety', 1, 5, '[{"type":"heading","content":"Roll Cage Safety"},{"type":"paragraph","content":"Roll cages are widely used in retail and warehousing. They cause thousands of injuries annually."},{"type":"bullet_points","items":["Crushed fingers and hands","Back and shoulder injuries","Foot injuries from rolling","Struck by falling goods","Cage collapse or tip-over"]},{"type":"highlight","content":"Loaded cages can weigh up to 500kg. They require proper training and respect."}]'),
    (m, 'Risk Assessment', 2, 5, '[{"type":"heading","content":"Risk Assessment"},{"type":"bullet_points","items":["Weight of loaded cage","Floor conditions — slopes, wet surfaces","Visibility while pushing","Congestion and narrow aisles","Cage condition — damaged wheels, bent frames","Time pressure increases risk"]},{"type":"subheading","content":"Controls"},{"type":"bullet_points","items":["Train all cage handlers","Remove damaged cages","Plan routes avoiding busy areas","Safety footwear is essential","Two-person handling for heavy loads"]},{"type":"infobox","content":"Manual Handling Operations Regulations 1992 apply to roll cage operations."}]'),
    (m2, 'Pushing and Pulling', 1, 5, '[{"type":"heading","content":"Safe Pushing Technique"},{"type":"paragraph","content":"ALWAYS push, never pull. Pushing uses body weight and gives better visibility."},{"type":"bullet_points","items":["Stand close, feet shoulder-width apart","Grip firmly with both hands at waist height","Back straight, legs generate force","Push smoothly, dont jerk","Look ahead","Slow at corners and blind spots","Use brakes to stop, not your body"]},{"type":"subheading","content":"Slopes"},{"type":"bullet_points","items":["Keep cage in front going downhill","Two people on steep slopes","Apply brakes before loading on slopes","Never leave unsecured on slopes"]},{"type":"highlight","content":"Push, dont pull. Keep cage in front at all times."}]'),
    (m2, 'Tight Spaces & Customer Areas', 2, 5, '[{"type":"heading","content":"Tight Spaces"},{"type":"bullet_points","items":["Plan route before moving","Clear obstacles first","Move slowly in confined areas","Use a spotter if needed","Communicate with colleagues","Never squeeze between cages"]},{"type":"subheading","content":"Customer Areas"},{"type":"bullet_points","items":["Move during quiet periods","Use barriers or cones","Never leave unattended without brakes","Watch for children","Be polite to customers"]},{"type":"note","content":"Customer safety is always paramount."}]'),
    (m3, 'Pre-Use Inspection & Loading', 1, 5, '[{"type":"heading","content":"Inspection & Loading"},{"type":"subheading","content":"Pre-Use Checklist"},{"type":"bullet_points","items":["All 4 wheels rotate freely","Brakes work correctly","Frame not bent or cracked","Shelves secure","Side panels locked","No sharp edges","Cage stands upright"]},{"type":"subheading","content":"Safe Loading"},{"type":"bullet_points","items":["Heaviest items at bottom","Even weight distribution","Dont exceed max capacity","Nothing protrudes beyond edges","Stack securely","Nothing above cage sides","Protect fragile items"]},{"type":"highlight","content":"An overloaded cage tipping can cause life-changing injuries."},{"type":"note","content":"This CPD course meets workplace safety training requirements for roll cage handling."}]');
